package store.app;
import store.model.*;import store.service.StoreService;import store.report.ReportService;import java.util.*;
public final class Main{static void line(String k,Object v){System.out.println(k+"="+v);}public static void main(String[]a)throws Exception{Catalog cat=new Catalog();Category office=new Category("C1","Office"),acc=new Category("C2","Accessories"),bags=new Category("C3","Bags");cat.addCategory(office);cat.addCategory(acc);cat.addCategory(bags);cat.addProduct(new Product("P1","Notebook",15,office));cat.addProduct(new Product("P2","Pen",5,office));cat.addProduct(new Product("P3","Mug",20,acc));cat.addProduct(new Product("P4","Backpack",80,bags));cat.addProduct(new Product("P5","Bottle",25,acc));StoreService s=new StoreService(cat);for(String id:new String[]{"P1","P2","P3","P4","P5"})s.initializeStock(id,Map.of("P1",100,"P2",200,"P3",40,"P4",15,"P5",30).get(id));s.register(new Customer("CU1","Ana",LoyaltyTier.REGULAR));s.register(new Customer("CU2","Bruno",LoyaltyTier.GOLD));s.register(new Customer("CU3","Carla",LoyaltyTier.SILVER));s.register(new Supplier("SU1","Alpha Supplies"));s.register(new Supplier("SU2","Beta Wholesale"));Promotion percentage=new PercentagePromotion(.10,200),fixed=new FixedPromotion(5,50,LoyaltyTier.GOLD),buy=new BuyXGetYPromotion("P2",2,1);s.registerPromotion(percentage);s.registerPromotion(fixed);s.registerPromotion(buy);Cart c=s.createCart("CU2");c.add(cat.product("P4"),1);c.add(cat.product("P1"),5);c.add(cat.product("P2"),10);c.add(cat.product("P5"),2);line("PRODUCTS",cat.size());line("CUSTOMERS",s.db.customers.size());line("SUPPLIERS",s.db.suppliers.size());line("CART_SUBTOTAL_BEFORE",c.subtotal());c.update("P1",6);line("CART_SUBTOTAL_AFTER_UPDATE",c.subtotal());c.remove("P5");line("CART_SUBTOTAL_AFTER_REMOVAL",c.subtotal());Order o1=s.createOrder("ORD1",c);s.applyPromotion(o1,percentage);s.applyShipping(o1,new ShippingRule(ShippingType.EXPRESS,25));line("ORD1_SUBTOTAL",o1.subtotal());line("ORD1_DISCOUNT",o1.discount());line("ORD1_SHIPPING",o1.shipping());line("ORD1_TOTAL",o1.total());s.pay("ORD1","PAY1",PaymentMethod.CARD);line("ORD1_STATUS",o1.status());Cart c2=s.createCart("CU1");c2.add(cat.product("P3"),1);c2.add(cat.product("P5"),1);Order o2=s.createOrder("ORD2",c2);s.applyShipping(o2,new ShippingRule(ShippingType.STANDARD,12));line("ORD2_SUBTOTAL",o2.subtotal());line("ORD2_DISCOUNT",o2.discount());line("ORD2_SHIPPING",o2.shipping());line("ORD2_TOTAL",o2.total());s.cancel("ORD2");line("ORD2_STATUS",o2.status());ReturnRequest r=s.requestReturn("RET1","ORD1");s.addReturnItem(r,"P1",1);line("RETURN_ID",r.id());line("RETURN_ITEMS","P1 x 1");line("REFUND_TOTAL",r.refundTotal());s.processReturn(r);Restock rest=s.restock("RST1","P3","SU1",5,18);line("RESTOCK_ID",rest.id());line("RESTOCK_ITEM",rest.product().id()+" x "+rest.quantity());line("RESTOCK_TOTAL",rest.total());s.manualOutflow("MAN1",10,"Store supplies");try{s.createOrder("BAD",new Cart("EMPTY",s.customer("CU1")));}catch(Exception e){line("INVALID_OPERATION_REJECTED",true);}s.exportInventory("inventory.csv");s.exportCashflow("cashflow.csv");line("INVENTORY_EXPORTED","inventory.csv");line("CASHFLOW_EXPORTED","cashflow.csv");line("FINAL_STOCK_P1",cat.product("P1").stock());line("FINAL_STOCK_P2",cat.product("P2").stock());line("FINAL_STOCK_P3",cat.product("P3").stock());line("FINAL_STOCK_P4",cat.product("P4").stock());line("FINAL_STOCK_P5",cat.product("P5").stock());new ReportService(s).printAll();}}
